insert into public.settings (key, value, value_type, group_key, label_ar, description_ar, is_public, sort_order) values
  ('start.timeline', '[{"years":0,"title":{"ar":"تبدا الحكاية","fr":"L''histoire commence"},"line":{"ar":"الزيتونة تتسجّل باسمك، ونتلهاو بيها من أوّل نهار.","fr":"L''olivier est à votre nom, et nous en prenons soin dès le premier jour."}},{"years":3,"title":{"ar":"أوّل حبّات","fr":"Les premières olives"},"line":{"ar":"الزيتونة الصغيرة تبدا تعطي أوّل حبّات الزيتون.","fr":"Le jeune olivier donne ses premières olives."}},{"years":7,"title":{"ar":"صابة كل عام","fr":"Une récolte chaque année"},"line":{"ar":"تولّي تعطي صابة كل عام، وقدّها يتبدّل حسب المطر والعام.","fr":"Il donne une récolte chaque année ; sa taille dépend de la pluie et de l''année."}},{"years":15,"title":{"ar":"شجرة كبيرة","fr":"Un arbre adulte"},"line":{"ar":"زيتونة كاملة، وقدّامها عشرات السنين.","fr":"Un olivier adulte, avec des décennies devant lui."}},{"years":40,"title":{"ar":"إرث للي بعدك","fr":"Un héritage"},"line":{"ar":"الزيتونة تعيش أكثر من عمر إنسان، وتبقى للعايلة.","fr":"L''olivier vit plus longtemps qu''une vie humaine et reste à la famille."}}]'::jsonb, 'json', 'start', 'الحاسبة: مراحل خطّ الوقت',
