insert into public.settings (key, value, value_type, group_key, label_ar, description_ar, is_public, sort_order) values
  ('start.timeline_title', to_jsonb('زيتونتك عبر السنين'::text), 'text', 'start', 'الحاسبة: عنوان خطّ الوقت', null, true, 2081),
  ('start.timeline_title_fr', to_jsonb('Votre olivier au fil des ans'::text), 'text', 'start', 'الحاسبة: عنوان خطّ الوقت (الفرنسي تحت العربي)', null, true, 2082),
  ('start.timeline_note', to_jsonb('تقديري لزيتونة جديدة: يتبدّل حسب الصنف والأرض والمطر والعناية. موش وعد بصابة ولا بربح.'::text), 'text', 'start', 'الحاسبة: ملاحظة خطّ الوقت (تقديري)', null, true, 2083),
  ('start.timeline_note_fr', to_jsonb('Indicatif, pour un jeune olivier : dépend de la variété, de la terre, de la pluie et des soins. Ce n''est une promesse ni de récolte ni de gain.'::text), 'text', 'start', 'الحاسبة: ملاحظة خطّ الوقت (تقديري) (الفرنسي تحت العربي)', null, true, 2084),
  ('start.timeline_age_label', to_jsonb('عمر ولدك ولا بنتك توّا (اختياري)'::text), 'text', 'start', 'الحاسبة: سؤال عمر الطفل في خطّ الوقت', null, true, 2085),
  ('start.timeline_age_label_fr', to_jsonb('Âge de votre enfant aujourd''hui (facultatif)'::text), 'text', 'start', 'الحاسبة: سؤال عمر الطفل في خطّ الوقت (الفرنسي تحت العربي)', null, true, 2086),
  ('start.timeline_age_then', to_jsonb('العمر وقتها: {age, plural, =0 {أقلّ من عام} one {عام} two {عامين} few {# سنين} other {# عام}}'::text), 'text', 'start', 'الحاسبة: عمر الطفل في كل مرحلة ({age} = العمر)', null, true, 2087),
  ('start.timeline_age_then_fr', to_jsonb('Son âge alors : {age, plural, =0 {moins d''un an} one {# an} other {# ans}}'::text), 'text', 'start', 'الحاسبة: عمر الطفل في كل مرحلة ({age} = العمر) (الفرنسي تحت العربي)', null, true, 2088)
